graphql.query:
mutation SetReaction {
				  setReaction(
				     request : {
				      bpId: 1,
				      uId: 1,
                      syncToken:0,
				      reaction: true
				    }
				  ) {
				  	id
				    content
				    createAt
				    likes
				  }
				}

mutation PinUnpinPost {
				 pinUnpinPost(uId:1 , bpId: 1 ){

				      content
				      id
				      author{
				      username
				     }

				}
				}

mutation FollowOrUnFollowAuthor{
				    followOrUnFollowAuthor(follower: 1, followee:3){
				        username
				        id
				    }
				}

 mutation BlockUser{
				           blockUser (blockerId: 1, blockedUserId:3){
				                username
				                id
				            }
				        }

 query GetPinnedPostsOfTheUser {
  getPinnedPostsOfTheUser(uId:1){


    content
    author{
        username
    }

  }
}
